"""Concise, source-linked portraits of the sixteen late-Han figures."""
from portrait_support import set_portrait


def life(text, bid, quote, note=''):
    volume = bid[1:4]
    work = {'v008-b0018-n01': '《吴书》', 'v001-b0098-n01': '《典略》', 'v008-b0047-n01': '《典略》'}.get(bid)
    title = f'《三国志》卷{int(volume)}' + (f'裴注引{work}' if work else '')
    return dict(text=text, sourceTitle=title,
                sourceUrl=f'/read/{volume}/#{bid}', quote=quote, note=note)


def apply(people, events, R):
    def put(pid, paragraphs, lifespan, milestones, relations=(), **kwargs):
        # Milestones carry the same reciprocal event membership as paragraph links.
        linked = dict((eid, '') for _, _, links in paragraphs for _, eid in links)
        for _, _, _, _, ids in milestones:
            for eid in ids:
                linked.setdefault(eid, '')
        added_roles = {('yuan-tan', 'guandu'): '随袁绍参战，兵败后一同退渡黄河'}
        additions = []
        for eid in linked:
            event = next(e for e in events if e['id'] == eid)
            if not any(p.get('personId') == pid for p in event['participants']):
                additions.append((eid, added_roles[(pid, eid)]))
        set_portrait(people, events, R, pid, paragraphs=paragraphs, lifespan=lifespan,
                     milestones=milestones, relations=relations,
                     participations=additions, **kwargs)

