    put('yuan-tan', [
        ('袁谭字显思，是袁绍的长子，被父亲派到青州。200年刘备被曹操击败，逃到青州，袁谭曾受刘备举为茂才，便率步骑迎接，并飞报袁绍，让刘备得到安顿和重聚旧部的机会。同年官渡兵败，他与袁绍一同退过黄河，袁氏势力仍保有河北大片州郡。', [('v006-b0032-n02','譚字顯思。','《典略》'),'v006-b0024','v032-b0009','v006-b0026'], [('官渡兵败','guandu')]),
        ('202年袁绍病死，谋臣分成两派，审配、逢纪拥立少子袁尚，袁谭不服，自称车骑将军。兄弟起初共同抵抗曹操，袁尚却不愿多分兵给他，袁谭一怒杀了逢纪。203年曹军暂退，兄弟转为内战，袁谭兵败守平原，派辛毗求曹操救援，换得一次喘息的机会。', ['v006-b0028','v006-b0030'], [('兄弟转为内战','yuan-succession')]),
        ('曹操答应援助，还以婚姻安排暂时稳住袁谭。204年曹军围邺，袁谭乘机夺取甘陵、安平、勃海、河间，又攻袁尚于中山，收纳其部众。曹操随后转兵讨他，袁谭放弃平原，退往南皮。205年正月南皮被攻破，他与郭图等被杀；袁氏长子的继承之争，最终没有保住父亲留下的土地。', ['v006-b0031','v006-b0032'], [])
    ], life('生年不详—205年','v006-b0032','十年正月，攻拔之，斬譚及圖等。','建安十年为205年；出生年与享年未载。'), [
        ('200年','迎接刘备','在青州接应败走的刘备，并报知袁绍。',['v032-b0009'],[]),
        ('202年','继承受阻','袁尚被拥立，袁谭自号车骑将军。',['v006-b0030'],['yuan-succession']),
        ('203年','求曹操救援','兄弟内战失利，派辛毗向曹操求救。',['v006-b0030'],['yuan-succession']),
        ('205年','南皮战死','曹操攻破南皮，杀袁谭及郭图。',['v006-b0032'],['yuan-succession'])
    ], [('yuanshao','父亲；袁谭为长子，受命掌青州却未能继位',['v006-b0024','v006-b0030']),('yuan-shang','弟弟，先同抗曹操，后争夺河北',['v006-b0030']),('liubei','曾受刘备举荐，后来率军迎其入青州',['v032-b0009'])], courtesy='显思', lead='袁绍长子，争位失利后借曹援，又在南皮败亡。')

    put('yuan-shang', [
        ('袁尚字显甫，是袁绍的少子，因相貌美而受父亲偏爱。袁绍想立他为后，却始终没有明确。202年袁绍死，审配、逢纪担心长子袁谭继位会危及自己，依照袁绍原先的意思拥立袁尚。袁谭不服，自号车骑将军，袁氏的家内争执从此变成了州郡与军队的分裂。', [('v006-b0032-n02','尚字顯甫。','《典略》'),'v006-b0028','v006-b0030'], [('拥立袁尚','yuan-succession')]),
        ('袁尚一度亲率军救援袁谭，共同抵抗曹操。203年曹军南退，兄弟随即交战，袁尚围攻平原，逼得袁谭向曹操求救。204年，他留下审配守邺，再出兵攻兄，曹操趁机围邺。他率万余人回援，在城外举火与守军呼应，却接连战败，连印绶、节钺也落入曹军，邺城最终失守。', ['v006-b0030','v006-b0031'], []),
        ('袁尚退至中山，又被袁谭击败，投奔兄长袁熙，部众尽失。205年二人再遭部将驱逐，逃往辽西乌桓，借其力量继续抵抗。207年曹操北征，袁尚、袁熙与乌桓合军战败，转逃辽东。他还想夺取公孙康的部众，公孙康却预设伏兵，将兄弟二人杀死，把首级送给曹操。', ['v006-b0032',('v006-b0032-n02','尚爲人有勇力，欲奪取康衆','《典略》')], [('曹操北征','wuhuan')])
    ], life('生年不详—207年','v006-b0032','十二年，太祖至遼西擊烏丸。尚、熙與烏丸逆軍戰，敗走奔遼東，公孫康誘斬之','建安十二年为207年；出生年与享年未载。'), [
        ('202年','继承袁氏','袁绍死后，审配等拥立其接位。',['v006-b0030'],['yuan-succession']),
        ('203年','兄弟内战','攻袁谭于平原，袁谭转向曹操求援。',['v006-b0030'],['yuan-succession']),
        ('204年','失去邺城','回援兵败，退至中山。',['v006-b0031'],['yuan-succession']),
        ('207年','辽东遇害','乌桓战败后奔公孙康，被诱杀送首。',['v006-b0032'],['wuhuan'])
    ], [('yuanshao','父亲；袁尚为少子，受其偏爱而被拥立继位',['v006-b0030']),('yuan-tan','兄长，争夺继承及河北地盘',['v006-b0030'])], courtesy='显甫', lead='继袁绍之位，与兄长内战失去河北，逃辽东后被杀。')

